// client/src/pages/CouponCenter.jsx (최종 수정 완료)

import React, { useEffect, useState } from 'react';
import { getMyCoupons, redeemCoupon } from '../api/couponApi';
import RouletteWheel from '../components/RouletteWheel';

function CouponCenter() {
        const [coupons, setCoupons] = useState([]);
        const [rewards, setRewards] = useState([]);
        const [showConfetti, setShowConfetti] = useState(false);
        const [isSpinning, setIsSpinning] = useState(false);
        const [rotationAngle, setRotationAngle] = useState(0);
        const [spinResult, setSpinResult] = useState(null);
        const [loading, setLoading] = useState(true);

        useEffect(() => {
                const load = async () => {
                        try {
                                setLoading(true);
                                const couponRes = await getMyCoupons();
                                setCoupons(couponRes.data || []);

                                const defaultRewards = [
                                        { name: 'MUSINSA 15% OFF', type: 'COUPON', probability: 18 },
                                        { name: 'Innisfree 샘플킷', type: 'COUPON', probability: 16 },
                                        { name: 'Olive Young 20% OFF', type: 'COUPON', probability: 12 },
                                        { name: 'Free Shipping', type: 'COUPON', probability: 8 },
                                        { name: '50 포인트', type: 'POINTS', probability: 20 },
                                        { name: '100 포인트', type: 'POINTS', probability: 10 },
                                        { name: '꽝', type: 'NONE', probability: 16 },
                                ];
                                setRewards(defaultRewards);
                        } catch (err) {
                                console.error(err);
                                setRewards([]);
                        } finally {
                                setLoading(false);
                        }
                };
                load();
        }, []);

        const weightedPick = (items) => {
                const total = items.reduce((s, it) => s + (it.probability || 0), 0);
                const r = Math.random() * total;
                let acc = 0;
                for (const it of items) {
                        acc += (it.probability || 0);
                        if (r <= acc) return it;
                }
                return items[items.length - 1];
        };

        const handleSpin = () => {
                if (isSpinning || rewards.length === 0) return;
                setIsSpinning(true);
                setSpinResult(null);

                const resReward = weightedPick(rewards);
                setSpinResult({ success: true, reward: resReward });

                const totalSegments = rewards.length;
                const segmentAngle = 360 / totalSegments;
                const rewardIndex = rewards.findIndex(r => r.name === resReward.name);
                // compute center angle of target segment then rotate so that center aligns with top (-90deg)
                const segmentCenterAngle = (rewardIndex + 0.5) * segmentAngle;
                const spins = 5; // full spins for animation
                const stopAngle = spins * 360 + (-90 - segmentCenterAngle);
                setRotationAngle(prev => prev + stopAngle);

                setTimeout(() => {
                        setIsSpinning(false);
                        // Show confetti effect
                        setShowConfetti(true);
                        setTimeout(() => setShowConfetti(false), 3000);
                        
                        // If coupon type, add a local coupon to user's list (simulated)
                        if (resReward.type === 'COUPON') {
                                const newCoupon = { _id: 'local-' + Date.now(), brand: resReward.name.split(' ')[0], code: 'LOCAL-' + Math.random().toString(36).slice(2,9), discount: resReward.name.match(/(\d+%)/)?.[0] || '', externalUrl: null, redeemed: false };
                                setCoupons(prev => [newCoupon, ...prev]);
                                alert(`🎉 당첨: ${resReward.name} — 쿠폰이 쿠폰함에 추가되었습니다.`);
                        } else if (resReward.type === 'POINTS') {
                                alert(`🎉 당첨: ${resReward.name} — 포인트가 지급되었습니다.`);
                        } else {
                                alert('아쉽지만 다음 기회에!');
                        }
                }, 4200);
        };

        const handleCopy = (code) => {
                try {
                        navigator.clipboard.writeText(code);
                        alert('쿠폰 코드가 복사되었습니다.');
                } catch (e) {
                        alert('클립보드 복사에 실패했습니다.');
                }
        };

        const handleRedeem = async (id) => {
                try {
                        const res = await redeemCoupon(id);
                        setCoupons(prev => prev.map(c => (c._id === id ? res.data : c)));
                        alert('쿠폰 사용 처리되었습니다.');
                } catch (err) {
                        alert('사용 실패: ' + (err.response?.data?.message || err.message));
                }
        };

        // pastel palette
        const pastel = {
                bg: '#fbfbfd',
                card: '#ffffff',
                accent1: '#ffdfe6', // pastel peach
                accent2: '#e8f7f1', // pastel mint
                accent3: '#e9e8ff', // pastel lavender
                softText: '#6b7280'
        };

        return (
                <div style={{ padding: 20, background: pastel.bg, minHeight: '80vh' }}>
                        <div style={{ maxWidth: 1100, margin: '0 auto' }}>
                                <h2 style={{ marginBottom: 6 }}>오늘의 브랜드 룰렛 & 쿠폰</h2>
                                <p style={{ color: pastel.softText }}>룰렛에 참여하여 제휴 브랜드의 쿠폰 또는 포인트를 즉시 획득하세요.</p>

                                <div style={{ display: 'flex', gap: 20, marginTop: 18, alignItems: 'flex-start' }}>
                                        {/* Left: Roulette Card */}
                                        <div style={{ flex: 1, background: pastel.card, borderRadius: 12, padding: 20, boxShadow: '0 10px 30px rgba(16,24,40,0.06)', overflow: 'hidden' }}>
                                                <div style={{ display: 'flex', gap: 20, alignItems: 'center', justifyContent: 'center' }}>
                                                        <div style={{ maxWidth: 360, width: '100%', display: 'flex', justifyContent: 'center' }}>
                                                                <RouletteWheel rewards={rewards} rotationAngle={rotationAngle} isSpinning={isSpinning} spinResult={spinResult} />
                                                        </div>

                                                        <div style={{ flex: 1 }}>
                                                                <h3 style={{ marginTop: 0 }}>오늘의 브랜드 룰렛</h3>
                                                                <p style={{ color: pastel.softText }}>매일 1회 무료 참여 · 추가 참여는 포인트로 결제</p>
                                                                <div style={{ marginTop: 12 }}>
                                                                        <button onClick={handleSpin} disabled={isSpinning} style={{ background: '#ff8a80', color: '#fff', border: 'none', padding: '12px 20px', borderRadius: 10, fontWeight: 800, boxShadow: '0 8px 24px rgba(255,138,128,0.12)', cursor: 'pointer' }}>{isSpinning ? '돌아가는 중...' : 'START'}</button>
                                                                </div>

                                                                {spinResult && (
                                                                        <div style={{ marginTop: 12, padding: 10, borderRadius: 8, background: pastel.accent3 }}>
                                                                                <strong>당첨: </strong> {spinResult.reward.name}
                                                                        </div>
                                                                )}
                                                        </div>
                                                </div>
                                        </div>

                                        {/* Right: Obtainable coupons list */}
                                        <div style={{ width: 340 }}>
                                                <div style={{ background: pastel.card, borderRadius: 12, padding: 16, boxShadow: '0 8px 20px rgba(16,24,40,0.04)' }}>
                                                        <h4 style={{ marginTop: 0 }}>획득 가능한 쿠폰</h4>
                                                        <div style={{ display: 'flex', flexDirection: 'column', gap: 10, marginTop: 8 }}>
                                                                {rewards && rewards.filter(r => r.type === 'COUPON').map((r, i) => (
                                                                        <div key={i} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: 10, borderRadius: 10, background: i % 2 === 0 ? pastel.accent1 : pastel.accent3 }}>
                                                                                <div>
                                                                                        <div style={{ fontWeight: 800 }}>{r.name.split(' ')[0]}</div>
                                                                                        <div style={{ color: pastel.softText, fontSize: 13 }}>{r.name}</div>
                                                                                </div>
                                                                                <div style={{ textAlign: 'right' }}>
                                                                                        <div style={{ fontWeight: 800, color: 'var(--primary)' }}>{r.probability}%</div>
                                                                                        <div style={{ fontSize: 12, color: pastel.softText }}>확률</div>
                                                                                </div>
                                                                        </div>
                                                                ))}
                                                        </div>
                                                </div>

                                                <div style={{ marginTop: 12, background: pastel.card, borderRadius: 12, padding: 12, boxShadow: '0 8px 20px rgba(16,24,40,0.04)' }}>
                                                        <h4 style={{ marginTop: 0 }}>내 쿠폰함</h4>
                                                        {coupons.length === 0 ? (
                                                                <p className="muted">현재 보유한 쿠폰이 없습니다.</p>
                                                        ) : (
                                                                <div style={{ display: 'grid', gridTemplateColumns: '1fr', gap: 10 }}>
                                                                        {coupons.map(c => (
                                                                                <div key={c._id} style={{ padding: 12, borderRadius: 10, background: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center', border: '1px solid #f0f0f4' }}>
                                                                                        <div>
                                                                                                <div style={{ fontWeight: 800 }}>{c.brand}</div>
                                                                                                <div style={{ color: pastel.softText }}>코드: <strong>{c.code}</strong></div>
                                                                                        </div>
                                                                                        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                                                                                                {c.externalUrl && <button onClick={() => { handleCopy(c.code); window.open(c.externalUrl, '_blank'); }} className="btn" style={{ padding: '8px 10px', borderRadius: 8, background: 'var(--primary)', color: '#fff' }}>사용처 이동</button>}
                                                                                                {!c.redeemed ? <button onClick={() => handleRedeem(c._id)} className="btn" style={{ padding: '8px 10px', borderRadius: 8, border: '1px solid #e6eefb' }}>사용</button> : <span style={{ color: 'green' }}>사용됨</span>}
                                                                                        </div>
                                                                                </div>
                                                                        ))}
                                                                </div>
                                                        )}
                                                </div>
                                        </div>
                                </div>
                        </div>
                </div>
        );
}

export default CouponCenter;
